def containsCycle(grid):
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    # Directions: right, down, left, up
    dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    for si in range(m):
        for sj in range(n):
            if visited[si][sj]:
                continue
            visited[si][sj] = True
            # Iterative DFS (avoids Python recursion limit); each entry: (x, y, parent_x, parent_y)
            stack = [(si, sj, -1, -1)]
            while stack:
                x, y, px, py = stack.pop()
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == grid[x][y]:
                        # Don't go back to the cell we just came from
                        if (nx, ny) == (px, py):
                            continue
                        # Visited same-valued neighbor that isn't our parent: cycle
                        if visited[nx][ny]:
                            return True
                        visited[nx][ny] = True
                        stack.append((nx, ny, x, y))
    return False
